// ─────────────────────────────────────────────────────────────────────────
//  01 · splitting a dollar by weight                                 ★★★
//  concepts: floor shares · largest-remainder distribution · ties to the lowest index
// ─────────────────────────────────────────────────────────────────────────

import static bootcamp.Check.*;

import java.util.*;

class Exercise {

    /** Weighted shares of totalCents that sum exactly to it (largest remainder, ties to lower index). */
    static long[] allocate(long totalCents, int[] weights) {
        long sumW = 0;
        for (int w : weights) sumW += w;
        int n = weights.length;
        long[] shares = new long[n];
        long[] rems = new long[n];
        long given = 0;
        for (int i = 0; i < n; i++) {
            shares[i] = totalCents * weights[i] / sumW;
            rems[i] = totalCents * weights[i] % sumW;
            given += shares[i];
        }
        var order = new ArrayList<Integer>();
        for (int i = 0; i < n; i++) order.add(i);
        order.sort((x, y) -> Long.compare(rems[y], rems[x]));
        for (int k = 0; k < totalCents - given; k++) shares[order.get(k)]++;
        return shares;
    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("equal remainders favour the lowest index", () ->
            eq(allocate(100, new int[] {1, 1, 1}), new long[] {34, 33, 33}));
        test("the spare cent goes to the largest remainder", () ->
            eq(allocate(1000, new int[] {3, 2, 1}), new long[] {500, 333, 167}));
        test("a single partner takes everything (boundary)", () ->
            eq(allocate(1000, new int[] {1}), new long[] {1000}));
        test("the shares sum exactly to the total", () ->
            eq(Arrays.stream(allocate(997, new int[] {2, 3, 5})).sum(), 997));
        test("an uneven split lands every cent", () ->
            eq(allocate(997, new int[] {2, 3, 5}), new long[] {199, 299, 499}));
        System.exit(report());
    }
    // ─── end tests ───────────────────────────────────────────────────────
}

