import java.math.RoundingMode;
import java.util.*;

class Exercise {

    /** amount × rate at scale 2, banker's rounding. */
    static BigDecimal convert(String amount, String rate) {
        return new BigDecimal(amount).multiply(new BigDecimal(rate)).setScale(2, RoundingMode.HALF_EVEN);
