import static bootcamp.Check.*;

import java.util.*;

class Exercise {

    /** pct% off, then offCents off. */
    static long percentThenFixed(long cents, int pct, long offCents) {
        return (cents * (100 - pct) + 50) / 100 - offCents;
    }

    /** offCents off, then pct% off. */
    static long fixedThenPercent(long cents, int pct, long offCents) {
        return ((cents - offCents) * (100 - pct) + 50) / 100;
    }

    /** The lower of the two prices. */
    static long cheaper(long cents, int pct, long offCents) {
        return Math.min(percentThenFixed(cents, pct, offCents), fixedThenPercent(cents, pct, offCents));
    }

